make('ic-dos-prop','Diferencia de proporciones','Intervalo aproximado para p₁−p₂ de muestras independientes.',[F('x1','Éxitos grupo 1','62'),F('n1','Tamaño grupo 1','100'),F('x2','Éxitos grupo 2','48'),F('n2','Tamaño grupo 2','100'),F('confidence','Confianza','0.95')],'(\\hat p_1-\\hat p_2)\\pm z^*\\sqrt{\\frac{\\hat p_1(1-\\hat p_1)}{n_1}+\\frac{\\hat p_2(1-\\hat p_2)}{n_2}}','El intervalo usa aproximación normal con varianzas estimadas por separado.','Si el intervalo contiene 0, la diferencia puede ser compatible con 0.','Para muestras pequeñas considera métodos de puntuación o exactos.',v=>{let x1=integer(v.x1,'x₁'),n1=integer(v.n1,'n₁',1),x2=integer(v.x2,'x₂'),n2=integer(v.n2,'n₂',1),c=prob(v.confidence,'confianza');if(x1>n1||x2>n2||c<=0||c>=1)throw Error('Comprueba éxitos, tamaños y confianza.');let p1=x1/n1,p2=x2/n2,d=p1-p2,se=Math.sqrt(p1*(1-p1)/n1+p2*(1-p2)/n2),z=normInv((1+c)/2),e=z*se;return{metrics:[metric('p₁ − p₂',d),metric('Límite inferior',d-e),metric('Límite superior',d+e),metric('Margen',e)],steps:[['Estimaciones',`\\hat p_1=${x1}/${n1}=${fmt(p1)},\\quad\\hat p_2=${x2}/${n2}=${fmt(p2)}`],['Error estándar',`EE=${fmt(se)}`],['Intervalo',`IC=[${fmt(d-e)},\\ ${fmt(d+e)}]`]],chart:chartBars(['Grupo 1','Grupo 2'],[p1,p2])}})
