make('spearman','Correlación de Spearman','Asociación monotónica mediante rangos.',[D('pairs','Pares x, y','1, 2\n2, 4\n3, 3\n4, 6\n5, 7\n6, 5')],'\\rho_s=\\operatorname{corr}(R_X,R_Y)','Transforma cada variable a rangos promedio y calcula su correlación de Pearson.','Detecta relaciones monotónicas incluso cuando no son lineales.','El valor p usa una aproximación t, especialmente para muestras pequeñas.',v=>{let p=pairs(v.pairs,3),n=p.length,rank=a=>{let s=a.map((x,i)=>({x,i})).sort((u,v)=>u.x-v.x),out=Array(n);for(let i=0;i<n;){let j=i+1;while(j<n&&s[j].x===s[i].x)j++;for(let k=i;k<j;k++)out[s[k].i]=(i+1+j)/2;i=j}return out},rx=rank(p.map(z=>z[0])),ry=rank(p.map(z=>z[1])),mx=mean(rx),my=mean(ry),sxx=sum(rx.map(z=>(z-mx)**2)),syy=sum(ry.map(z=>(z-my)**2)),sxy=sum(rx.map((z,i)=>(z-mx)*(ry[i]-my)));if(!sxx||!syy)throw Error('Ambas variables deben variar.');let rho=sxy/Math.sqrt(sxx*syy),t=Math.abs(rho)===1?Infinity:rho*Math.sqrt((n-2)/(1-rho*rho)),pv=Number.isFinite(t)?twoTail(z=>tCDF(z,n-2),t):0;return{metrics:[metric('ρ de Spearman',rho),metric('Valor p aprox.',pv),metric('n',n)],steps:[['Rangos',`R_X=(${rx.map(fmt).join(',\\ ')})`],['Correlación de rangos',`\\rho_s=${fmt(rho)}`]],chart:chartScatter(p),table:{headers:['x','y','Rango x','Rango y'],rows:p.map((z,i)=>[fmt(z[0]),fmt(z[1]),fmt(rx[i]),fmt(ry[i])])}}})
