let currentGroup=groups[0],currentModule=groups[0].modules[0],searchTerm='';
function texMarkup(tex){return `<div class="math-display" data-tex="${esc(tex)}"><span class="math-fallback">${esc(tex)}</span></div>`}
function renderMath(){if(!window.katex)return;$$('.math-display[data-tex]').forEach(el=>{try{window.katex.render(el.dataset.tex,el,{throwOnError:false,displayMode:true,strict:'ignore'})}catch(e){}})}
function renderNav(){let nav=$('#sidebarNav');nav.innerHTML=groups.map(g=>`<div class="nav-group"><button class="nav-item ${g===currentGroup?'active':''}" data-group="${g.id}" ${searchTerm&&!`${g.label} ${g.modules.map(m=>m.title).join(' ')}`.toLowerCase().includes(searchTerm)?'hidden':''}><span class="nav-icon">${g.icon}</span><span>${g.label}</span><span class="nav-count">${String(g.modules.length).padStart(2,'0')}</span></button></div>`).join('');$$('[data-group]',nav).forEach(b=>b.onclick=()=>selectGroup(groups.find(g=>g.id===b.dataset.group)))}
function animatePage(){const main=$('#main');main.classList.remove('animate-page');void main.offsetWidth;main.classList.add('animate-page')}
function selectGroup(g){currentGroup=g;currentModule=g.modules[0];render();animatePage();document.body.classList.remove('menu-open')}
function selectModule(m){currentModule=m;renderModule();animatePage()}
function render(){renderNav();$('#breadcrumbTopic').textContent=currentGroup.label;$('#topicEyebrow').textContent=currentGroup.eyebrow;$('#topicTitle').textContent=currentGroup.title;$('#topicDescription').textContent=currentGroup.description;renderModule()}
function renderModule(){let m=currentModule,index=currentGroup.modules.indexOf(m)+1;$('#moduleCounter').textContent=`CALCULADORA ${String(index).padStart(2,'0')} / ${String(currentGroup.modules.length).padStart(2,'0')}`;$('#moduleTitle').textContent=m.title;$('#moduleDescription').textContent=m.description;$('#tabStrip').innerHTML=currentGroup.modules.map(t=>`<button class="tab-btn ${m===t?'active':''}" role="tab" aria-selected="${m===t}" data-tab="${t.id}">${esc(t.title)}</button>`).join('');$$('[data-tab]').forEach(b=>b.onclick=()=>selectModule(currentGroup.modules.find(t=>t.id===b.dataset.tab)));$('#guideTitle').textContent=m.title;$('#guideText').textContent=m.guide;$('#guideInterpretation').textContent=m.interpretation;$('#tipText').textContent=m.tip;$('#guideFormula').outerHTML=texMarkup(m.formula).replace('<div class="math-display"','<div id="guideFormula" class="math-display"');$('#inputFields').innerHTML=m.fields.map(f=>`<div class="field ${f.type==='textarea'?'wide':''}"><label for="f-${f.key}">${esc(f.label)}</label>${f.type==='textarea'?`<textarea id="f-${f.key}" data-key="${f.key}">${esc(f.value)}</textarea>`:f.type==='select'?`<select id="f-${f.key}" data-key="${f.key}">${f.options.map(o=>`<option value="${esc(o[0])}" ${o[0]===f.value?'selected':''}>${esc(o[1])}</option>`).join('')}</select>`:`<input id="f-${f.key}" data-key="${f.key}" type="${f.type==='text'?'text':'number'}" step="any" value="${esc(f.value)}">`}${f.help?`<div class="field-help">${esc(f.help)}</div>`:''}</div>`).join('');$('#inputStatus').textContent='';calculate();renderMath()}
function chartSVG(chart){if(!chart)return'';let W=640,H=245,pad={l:45,r:18,t:18,b:43},iw=W-pad.l-pad.r,ih=H-pad.t-pad.b;
 if(chart.type==='bar'){let vals=chart.values,max=Math.max(0,...vals),min=Math.min(0,...vals),range=Math.max(1,max-min),zero=pad.t+ih*max/range,barW=iw/vals.length*.66;return `<svg viewBox="0 0 ${W} ${H}" role="img" aria-label="Gráfico de barras"><line x1="${pad.l}" y1="${zero}" x2="${W-pad.r}" y2="${zero}" stroke="#bac9d4"/>${vals.map((v,i)=>{let x=pad.l+(i+.5)*iw/vals.length-barW/2,y=pad.t+(max-v)/range*ih,h=Math.max(1,Math.abs(zero-y));return `<rect x="${x}" y="${Math.min(y,zero)}" width="${barW}" height="${h}" rx="3" fill="${chart.color}" opacity=".9"><title>${esc(chart.labels[i])}: ${fmt(v)}</title></rect>`}).join('')}${chart.labels.map((l,i)=>`<text x="${pad.l+(i+.5)*iw/vals.length}" y="${H-16}" text-anchor="middle" fill="#7c8da0" font-size="${vals.length>16?8:11}">${esc(String(l).slice(0,8))}</text>`).join('')}</svg>`}
 let points=chart.points,xs=points.map(p=>p[0]),ys=points.map(p=>p[1]),minX=Math.min(...xs),maxX=Math.max(...xs),minY=Math.min(0,...ys),maxY=Math.max(...ys),dx=maxX-minX||1,dy=maxY-minY||1,X=x=>pad.l+(x-minX)/dx*iw,Y=y=>pad.t+(maxY-y)/dy*ih,axis=`<line x1="${pad.l}" y1="${pad.t+ih}" x2="${W-pad.r}" y2="${pad.t+ih}" stroke="#bac9d4"/><line x1="${pad.l}" y1="${pad.t}" x2="${pad.l}" y2="${pad.t+ih}" stroke="#bac9d4"/><text x="${pad.l}" y="${H-16}" fill="#8a9cad" font-size="11">${fmt(minX,2)}</text><text x="${W-pad.r}" y="${H-16}" text-anchor="end" fill="#8a9cad" font-size="11">${fmt(maxX,2)}</text>`;
 if(chart.type==='scatter'){let line=chart.line?`<line x1="${X(chart.line[0][0])}" y1="${Y(chart.line[0][1])}" x2="${X(chart.line[1][0])}" y2="${Y(chart.line[1][1])}" stroke="#5377db" stroke-width="2.5"/>`:'';return `<svg viewBox="0 0 ${W} ${H}" role="img" aria-label="Diagrama de dispersión">${axis}${line}${points.map(p=>`<circle cx="${X(p[0])}" cy="${Y(p[1])}" r="5" fill="#3ac7a4" stroke="white" stroke-width="2"><title>${fmt(p[0])}, ${fmt(p[1])}</title></circle>`).join('')}</svg>`}
 let sorted=[...points].sort((a,b)=>a[0]-b[0]),path=sorted.map((p,i)=>`${i?'L':'M'}${X(p[0]).toFixed(2)} ${Y(p[1]).toFixed(2)}`).join(' '),shade=chart.shade?`<rect x="${X(Math.max(minX,chart.shade[0]))}" y="${pad.t}" width="${Math.max(0,X(Math.min(maxX,chart.shade[1]))-X(Math.max(minX,chart.shade[0])))}" height="${ih}" fill="#5ad5ba" opacity=".16"/>`:'';return `<svg viewBox="0 0 ${W} ${H}" role="img" aria-label="Curva de distribución">${axis}${shade}<path d="${path}" fill="none" stroke="#3cc7a9" stroke-width="3" stroke-linejoin="round" stroke-linecap="round"/></svg>`}
function calculate(){let values={};$$('#inputFields [data-key]').forEach(el=>values[el.dataset.key]=el.value);try{let r=currentModule.calc(values);$('#inputStatus').textContent='';$('#resultSection').innerHTML=`<div class="section-caption">◈ RESULTADOS</div><div class="metric-grid">${(r.metrics||[]).map(x=>`<div class="metric"><label>${esc(x.label)}</label><strong>${esc(x.value)}</strong></div>`).join('')}</div>${r.note?`<p class="result-note">${esc(r.note)}</p>`:''}${r.chart?`<div class="chart-wrap"><h4>Visualización</h4>${chartSVG(r.chart)}</div>`:''}${r.table?`<div class="table-wrap"><h4>Tabla de cálculo</h4><table><thead><tr>${r.table.headers.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${r.table.rows.map(row=>`<tr>${row.map(cell=>`<td>${esc(cell)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`:''}${r.steps?`<div class="steps-wrap"><h4>Desarrollo paso a paso</h4>${r.steps.map((s,i)=>`<div class="step"><span class="step-num">${i+1}</span><div class="step-content"><strong>${esc(s[0])}</strong>${s[1].includes('\\')?texMarkup(s[1]):`<p>${esc(s[1])}</p>`}</div></div>`).join('')}</div>`:''}`;renderMath()}catch(e){$('#inputStatus').textContent=e.message;$('#resultSection').innerHTML=`<div class="result-placeholder"><span>◈</span><strong>Revisa los datos de entrada</strong><p>${esc(e.message)}</p></div>`}}
$('#calculateBtn').onclick=calculate;$('#exampleBtn').onclick=()=>{currentModule.fields.forEach(f=>{let el=$(`#f-${f.key}`);if(el)el.value=f.value});calculate()};$('#menuBtn').onclick=()=>document.body.classList.toggle('menu-open');$('#sourceBtn').onclick=$('#sourceBottomBtn').onclick=()=>$('#sourcesDialog').showModal();$('#closeSources').onclick=()=>$('#sourcesDialog').close();$('#sourcesDialog').onclick=e=>{if(e.target===$('#sourcesDialog'))e.target.close()};$('#searchInput').oninput=e=>{searchTerm=e.target.value.trim().toLowerCase();renderNav();if(searchTerm){let found=groups.flatMap(g=>g.modules.map(m=>({g,m}))).find(x=>x.m.title.toLowerCase().includes(searchTerm)||x.g.label.toLowerCase().includes(searchTerm));if(found){currentGroup=found.g;currentModule=found.m;render()}else{$('#tabStrip').innerHTML='<span class="field-help">No se encontraron temas.</span>'}}else render()};document.addEventListener('keydown',e=>{if(e.key==='/'&&document.activeElement.tagName!=='INPUT'&&document.activeElement.tagName!=='TEXTAREA'){e.preventDefault();$('#searchInput').focus()}if(e.key==='Escape')document.body.classList.remove('menu-open')});render();

